SELECT COUNT(*) FROM households 
WHERE LOWER(TRIM(socioeconomic->>'Tenure_Type')) IN ('owned', 'own')
AND socioeconomic->'Income_Bracket' IN ('More than R$ 26,400', 'More than R$ 22,000 and less than R$ 26,400');

SELECT COUNT(*) FROM households 
WHERE LOWER(TRIM(socioeconomic->>'Tenure_Type')) IN ('owned', 'own')
AND REGEXP_REPLACE(TRIM(socioeconomic->>'Income_Bracket'), '\s+', ' ', 'g') IN ('More than R$ 26,400', 'More than R$ 22,000 and less than R$ 26,400');

SELECT housenum, socioeconomic->>'Tenure_Type' as tenure, socioeconomic->>'Income_Bracket' as income FROM households 
WHERE LOWER(TRIM(socioeconomic->>'Tenure_Type')) IN ('owned', 'own')
AND REGEXP_REPLACE(TRIM(socioeconomic->>'Income_Bracket'), '\s+', ' ', 'g') IN ('More than R$ 26,400', 'More than R$ 22,000 and less than R$ 26,400');

